namespace Praktikaportaal.Core.Interfaces;

/// <summary>
/// Stores uploaded files outside the web root. Files are addressed by an opaque storage key
/// generated by the storage (never by the user-supplied file name).
/// </summary>
public interface IFileStorage
{
    /// <summary>Saves the stream under a new random key and returns the key.</summary>
    /// <param name="extension">Lower-case extension with dot, e.g. ".pdf".</param>
    Task<string> SaveAsync(Stream content, string extension, CancellationToken ct = default);

    /// <summary>Opens the stored file for reading. Throws <see cref="FileNotFoundException"/> if missing.</summary>
    Stream OpenRead(string storageKey);

    /// <summary>Deletes the file; does nothing if it does not exist.</summary>
    Task DeleteAsync(string storageKey, CancellationToken ct = default);
}
